\@gobble{assump: regularity}
For each $q \in \mathcal{Q}_{\text{tr}}$,  the pair $(E_q,A_q)$ is \emph{regular}, i.e., the characteristic polynomial $\text{det}(sE_q -A_q)$ is not identically zero. Moreover, the Quasi-Weierstrass form \eqref{QWform1} of the pair $(E_q, A_q)$ is such that the nilpotent block $N_q$  has index at most one, i.e., $N_q = 0$. 
\hfill \qed

\@gobble{thm:ISS_like}
Suppose that Assumptions~\ref{assumpregdae}-\ref{assump: matrices} hold.
Choose any $ {\mu>\max\{0,\ln\gamma\}}$ and any
$\theta\in(0,e^\mu/\gamma-1)$, and suppose that
$\mu/\lambda<\tau_d$. Let
$\kappa:=e^{-\mu}(1+\theta)\gamma$, $\eta:=\min\left\{
\lambda-\frac{\mu}{\tau_d},-\ln\kappa
\right\}$. Then, every solution of system~\eqref{eqn: equiv_2} satisfies the following bound for all $(t,j) \in \mathrm{dom}(y)$:

\begin{equation}\@gobble{eq: kl_bound}
    |y(t,j)|_{\mathcal{A}} \;\leq\; \beta\!\left(|y(0,0)|_{\mathcal{A}},\, t+j\right) + \nu(\alpha),
\end{equation}

where $\beta(r,s):= (\frac{{\rm e}^{\mu N_0}\,\overline{p}}{\underline{p}})^{0.5}\rm e^{-\eta s/2}\, r$, and $\nu(\alpha):=\sqrt{(\bar{c}/\underline{c})\alpha}$,  $\bar{c}={\rm e}^{\mu N_0}\bigl(1+\tfrac{1}{\theta}\bigr)$, $\underline{c}=\underline{p}\,\bigl({\rm e}^{\mu} - (1+\theta)\gamma\bigr)$.

\hfill $\square$

\normalfont{
Theorem~\ref{thm:ISS_like} gives a lower bound on $\tau_d$, and thus on the switching rate, guaranteeing global practical stability of \eqref{eqn: equiv_2} with respect to $\mathcal{A}$. The residual neighborhood $\nu(\alpha)$ depends on the maximum projected-equilibrium mismatch $\alpha$, rather than the distance between the original equilibria. In particular, $\alpha=0$ iff $\Pi_r(\xi_q^*)=\xi_r^*$ for all admissible transitions, in which case $\mathcal{A}$ is UGAS. This includes the common-equilibrium setting of~\cite{trenn2012switched}, while also allowing mode-dependent equilibria compatible under the consistency projections.
} \hfill \qed

\@gobble{thm: SGPAS}
    Let $N_0=1$ and suppose that Assumptions \ref{assumpregdae},  \ref{assump: regularity}, and \ref{assump: matrices} hold. Let 

\begin{align}
\mathcal{A}
:=
\bigcup_{q\in\mathcal{Q}_{\mathrm{tr}}}
\Bigg[
&\{\xi_q^\star\}\times\{q\}\times[0,1]\notag
\\
&{}\cup
\bigcup_{\substack{r\in\mathcal{Q}_{\mathrm{tr}}\\ r\neq q}}
\overline{
\left\{
\Theta_r^t\bigl(\Pi_r(\xi_q^\star)\bigr)
:
t\geq 0
\right\}}
\times\{r\}\times\{0\}
\Bigg].
\end{align}


    Then, the set $\mathcal{A}$ is SGPAS as $1/\tau_d \to 0^+$ for system \eqref{eqn: eqiv_HI}.

\normalfont{
Compared with Theorem~\ref{thm:ISS_like}, Theorem~\ref{thm: SGPAS} more precisely characterizes the asymptotic behavior for sufficiently large $\tau_d$. In particular, $\mathcal Y:=\operatorname{proj}_{\xi}(\mathcal A)$ consists of the mode-dependent equilibria and the trajectories flowing from $\Pi_r(\xi_q^\star)$ toward $\xi_r^\star$, for $r\neq q$. Theorem~\ref{thm: SGPAS} guarantees convergence to an arbitrarily small neighborhood of $\mathcal Y$.
}\hfill\qed

\@gobble{definitionReachable}
    Let $K \subset \mathbb{R}^n$ be a compact set. The (infinite horizon) reachable set from $K$ for the hybrid inclusion \eqref{eqn:hy_sys_def}, denoted as $R(K)$, is defined as $R(K) \coloneqq \{z \in \mathbb{R}^n  :  z=\xi(t,j), \xi \in \mathcal{S}(K), (t,j) \in \text{dom}(\xi)\}$,  where $\mathcal{S}(K)$ denotes the set of solutions to  \eqref{eqn:hy_sys_def} with initial conditions in $K$.
\hfill \qed

\@gobble{defn: cons_space}
Given $q \in \mathcal{Q}$, the \emph{consistency space} $\mathcal{C}_q$ of the $q^{\text{th}}$ mode of system \eqref{eqn: affine_DAE} is defined as:

    \begin{align*}
        \mathcal{C}_q \coloneqq \{ &\xi_0 \in \mathbb{R}^n \, : \, \exists~\tau>0~\text{and}~\text{a continuously differentiable} \\
        & \text{ function } \xi : [0, \tau] \to \mathbb{R}^n \text{ s.t. }\, E_q \Dot{\xi}(t) = A_q \xi(t) + b_q,\\
        &~~\forall \, t \in (0,\tau)\}.
    \end{align*}
    In other words, $\mathcal{C}_q$ denotes the set of initial conditions for which there exists a solution to \eqref{eqn: affine_DAE}.
    \hfill \qed

\@gobble{lem: QWF}
Suppose that the pair $(E_q, A_q)$ is regular, where $q \in \mathcal{Q}$. Then, there exist invertible matrices $T_q \coloneqq [V_q, W_q]$ and $S_q \coloneqq [E_qV_q, A_qW_q]^{-1}$ that transform $(E_q, A_q)$ into the \emph{Quasi-Weierstrass form}:

    \begin{equation}\@gobble{QWform}
        (S_q E_q T_q, S_q A_q T_q) = \left ( \begin{bmatrix}
            I_{n^q_1} & 0 \\
            0 & N_q
        \end{bmatrix}, \begin{bmatrix}
            J_q & 0 \\
            0 & I_{n^q_2}
        \end{bmatrix} \right ),
    \end{equation}

    for some $J_q \in \mathbb{R}^{n_1^q \times n^q_1}$ and a nilpotent matrix $N_q \in \mathbb{R}^{n_2^q \times n_2^q}$, where $(N_q)^{n_2^q} = 0$, $n_1^q + n_2^q = n$, $V_q \in \mathbb{R}^{n \times n_1^q}$, and $W_q \in \mathbb{R}^{n \times n^q_2}$. \hfill \qed

\@gobble{lem: characterization}
Let Assumption \ref{assump: regularity} hold. Then, $\mathcal{C}_q =  \{\xi \in \mathbb{R}^n \, : \, \xi \in (\text{span}(V_q) - W_q b^a_q)\}$,~$\forall~q\in\mathcal{Q}$. 
\hfill \qed

\@gobble{defn: diff_proj}
  Given a $q \in \mathcal{Q}$, the \emph{differential projector} of the $q^{th}$ mode of \eqref{eqn: affine_DAE} is given by $\Pi_{q}^{\text{diff}}  = T_q \begin{bmatrix}
            I_{n^q_1} & 0 \\
            0 & 0_{n^q_2}
        \end{bmatrix} S_q$, where $T_q$ and $S_q$ are given by Lemma \ref{lem: QWF}. \hfill $\square$

\@gobble{defn: imp_proj}
   Given $q \in \mathcal{Q}$, the \emph{impulse projector} of the $q^{\text{th}}$ mode of the system \eqref{eqn: affine_DAE} is given by $\Pi_q^{\text{imp}} = T_q \begin{bmatrix}
            0 & 0 \\ 0 & I_{n^q_2} 
        \end{bmatrix} S_q$, where $T_q$ and $S_q$ are given by Lemma \ref{lem: QWF}. \hfill $\square$

\@gobble{prop: ols_dae}
    Assume $N_0=1$ and suppose that Assumptions
\ref{assumpregdae}, \ref{assump: regularity},
and \ref{assump: matrices} hold. Then, the sets $\mathcal{B}$ and
    \begin{align}
\mathcal{A}
:=
\bigcup_{q\in\mathcal{Q}_{\mathrm{tr}}}
\Bigg[
&\{\xi_q^\star\}\times\{q\}\times[0,1]
\\
&{}\cup
\bigcup_{\substack{r\in\mathcal{Q}_{\mathrm{tr}}\notag\\ r\neq q}}
\overline{
\left\{
\Theta_r^t\bigl(\Pi_r(\xi_q^\star)\bigr)
:
t\geq 0
\right\}}
\times\{r\}\times\{0\}
\Bigg].
\end{align}
    are equal.

Let $K^j_{q}:=  (\left(\{\xi^*_q\} + (j+1)^{-1} \mathbb{B})\cap\mathcal{C}_q\right) \times \{q\} \times [0, 1]$ and $K^\infty_{q}:= \{\xi^*_q\} \times \{q\} \times [0, 1]$. Note that $\mathcal{A}_{j,q} = \overline{R(K^j_q)}$. Since $K^\infty_{q}\subset K^j_{q}$, for all $j\geq 0$, we have $\overline{R\left (K^\infty_{q}\right )} \subseteq \mathcal{A}_{j,q}$ for all $j\in\mathbb{Z}_{\geq 0}$. Hence $\overline{R\left (K^\infty_{q}\right )} \subseteq \bigcap_{j\in\mathbb{Z}_{\geq 0}} \mathcal{A}_{j,q} = \mathcal{A}_{q} \subset \mathcal{B}$. To show the other direction, we note that since $N_0=1$, system \eqref{eqn: ideal_hybrid} can experience at most one jump. Therefore, for any $\phi \in \mathcal{S}(K^j_q)$, one of the following must hold true: 1) \text{dom}($\phi$) = $[0, \infty) \times \{0\}$; 2) \text{dom}($\phi$) = $[0,t_1] \times \{0\} \cup [t_1,\infty) \times \{1\}$, for some $t_1 \geq 0$.  Let us consider the first possibility. It is clear that 

    \begin{equation*}
        \phi(t,0) = (\Theta_q^t(\xi(0,0)), q,\tau(0,0)), \, \forall (t,0) \in \text{dom}(\phi),
    \end{equation*}

    where $\xi(0,0) \in \{\xi^*_q\} + (j+1)^{-1} \mathbb{B}$, $q\in\mathcal Q_{\mathrm{tr}}$, and $\tau(0,0) \in [0,1]$. Since $\xi^*_q$ is globally asymptotically stable for the $q^{\text{th}}$ mode of System \eqref{eqn: ideal_hybrid}, there exists a constant $c_1 >0$ such that $\Theta^t_q(\xi(0,0)) \in \left (\{\xi^*_q\} + c_1(j+1)^{-1} \mathbb{B}  \right )\cap\mathcal{C}_q$, for all $(t,0) \in \text{dom}(\phi)$. Therefore,

    \begin{align*}
        \phi(t,i)&\in ((\{\xi^*_q\} + c_1(j+1)^{-1} \mathbb{B})\cap\mathcal{C}_q) \times \{q\} \times [0, 1]
    \end{align*}
    for all $(t,i)\in \text{dom}(\phi)$.

    \par Now, we consider the second possibility. For all $(t,0) \in \text{dom}(\phi)$, we have  $\phi(t,0) = (\Theta_q^t(\xi(0,0)), q,\tau(0,0))$. Now, for $(t,1) \in \text{dom}(\phi)$ we have 

    \begin{equation*}
        \phi(t,1) = (\Theta^{t-t_1}_{q^+} \circ \Pi_{q^+} \circ \Theta_q^{t_1}(\xi(0,0)), q^+, 0). 
    \end{equation*}

    Similar to the previous possibility, there exists a constant $c_1 >0$ such that  $\Theta^t_q(\xi(0,0)) \in \left (\{\xi^*_q\} + c_1(j+1)^{-1} \mathbb{B}  \right )\cap\mathcal{C}_q$, for all $(t,0) \in \text{dom}(\phi)$. Since \textcolor{black}{$L_{q^+}$ is the linear part of $\Pi_{q^+}$, the map $\Pi_{q^+}$ is Lipschitz with constant $l_{q^+} := \|L_{q^+}\|_2$}. Therefore, the image of
$\{\xi_q^\star\}+c_1(j+1)^{-1}\mathbb B$
under $\Pi_{q^+}$ is contained in
$\{\Pi_{q^+}(\xi_q^\star)\}
+c_1l_{q^+}(j+1)^{-1}\mathbb B.
$. Thus, for all $(t,1) \in \text{dom}(\phi)$ we have

    \begin{align*}
\Theta_{q^+}^{t-t_1}
\circ\Pi_{q^+}
\circ&\Theta_q^{t_1}(\xi(0,0))
\in
\Bigl\{
\Theta_{q^+}^{t-t_1}(\xi)
:\,\notag\\
&\bigl|\xi-\Pi_{q^+}(\xi_q^\star)\bigr|
\leq c_1l_{q^+}(j+1)^{-1}
\Bigr\}.
\end{align*}





    Since $\xi^*_{q^+}$ is globally exponentially stable for the $(q^+)^{\text{th}}$ mode of System \eqref{eqn: ideal_hybrid} (a direct consequence of Assumption \ref{assump: matrices}), \textcolor{black}{there exists $c_2 \geq 1$ such that $\|e^{A_{q^+}^{\mathrm{diff}} t}\| \leq c_2$ for all $t \geq 0$ and $q^+ \in \mathcal{Q}_{\text{tr}}$ (see, e.g.,~\cite[Thm.~4.4]{trenn2012switched}).} \textcolor{black}{Consequently}, there exists a constant $c_2 >0$ such that for all $t \geq 0$ and $q \in \mathcal{Q}_{\text{tr}}$,

       \begin{equation*}
\left|
\Theta_q^t(\xi)-\Theta_q^t(\xi')
\right|
\leq
c_2|\xi-\xi'|,
\qquad
\forall\,\xi,\xi'\in\mathcal C_q,
\quad t\geq0.
\end{equation*}

    As a result we get 

    \begin{align}
        \@gobble{eqn: containment}
        \{ &\Theta_{q^+}^{t-t_1}(\xi) \, : \, \lvert \xi - \Pi_{q^+}(\xi^*_q) \vert  \leq c_1 \cdot l_{q^+} (j+1)^{-1}\} \subset \nonumber \\
        & \{\Theta_{q^+}^{t-t_1}(\Pi_{q^+} \xi^*_q)\} + c_1 \cdot l_{q^+} \cdot c_2 (j+1)^{-1} \mathbb{B}. 
    \end{align}

    It is clear now that for all $(t,1) \in \text{dom}(\phi)$,





    \begin{align*}
\phi(t,1)
\in
\bigcup_{q^+\in\mathcal Q_{\mathrm{tr}}\setminus\{q\}}
\Bigl(
&
\bigl\{
\Theta_{q^+}^{t-t_1}
\bigl(\Pi_{q^+}(\xi_q^\star)\bigr)
\bigr\}
\\
&{}
+c_1c_2l(j+1)^{-1}\mathbb B
\Bigr)
\times\{q^+\}\times\{0\}.
\end{align*}

    where $l \coloneqq \max_{r \in \mathcal{Q}_{\text{tr}}} \lVert \textcolor{black}{L_r} \rVert$.

    From the above arguments:

    \begin{align*}
        R(K_q^\infty)
        ={}&
        \{\xi_q^\ast\}\times\{q\}\times[0,1]
        \nonumber\\
        &\cup
        \bigcup_{r\in\mathcal{Q}_{\text{tr}}\setminus\{q\}}
        \{\Theta_r^t(\Pi_r(\xi_q^\ast)):t\geq0\}
        \times\{r\}\times\{0\}.
    \end{align*}

    Since each subsystem has an exponentially stable equilibrium point, we also have

    \begin{align}
        &\overline{R(K_q^\infty)}
        ={}
        \{\xi_q^\ast\}\times\{q\}\times[0,1]
        \nonumber\\
        &\cup
        \bigcup_{r\in\mathcal{Q}_{\text{tr}}\setminus\{q\}}
        \left(
        \{\Theta_r^t(\Pi_r(\xi_q^\ast)):t\geq0\}
        \cup\{\xi_r^\ast\}
        \right)
        \times\{r\}\times\{0\}.
        \@gobble{eq:closureR0Kinf}
    \end{align}

    We now show that $\mathcal{A}_q=
    \overline{R(K_q^\infty)}$. Indeed, since $K_q^\infty\subset K_q^j$ for every
$j\in\mathbb{Z}_{\geq0}$, it follows that $R(K_q^\infty)
    \subseteq
    R(K_q^j)$, and therefore $\overline{R(K_q^\infty)}
    \subseteq
    \overline{R(K_q^j)}
    =
    \mathcal{A}_{j,q}$ for every $j\in\mathbb{Z}_{\geq0}$. Thus,

\begin{equation}
    \overline{R(K_q^\infty)}
    \subseteq
    \bigcap_{j\in\mathbb{Z}_{\geq0}}\mathcal{A}_{j,q}
    =
    \mathcal{A}_q.
\@gobble{eq:first-inc}
\end{equation}

To show the other inclusion, we define the constant $c_3 \coloneqq \max \{c_1, c_1 \cdot c_2 \cdot l\}$. Using the containment in \eqref{eqn: containment}, it is clear that  $R(K_q^j)
    \subseteq
    R(K_q^\infty)
    +c_3(j+1)^{-1}\mathbb{B}$. Taking the closure on both sides gives us,  $\mathcal{A}_{j,q}
    =
    \overline{R(K_q^j)}
    \subseteq
    \overline{
    R(K_q^\infty)
    +c_3(j+1)^{-1}\mathbb{B}}$. Since $R(K_q^\infty)
    \subseteq
    \overline{R(K_q^\infty)}$ we further obtain $\mathcal{A}_{j,q}
    \subseteq
    \overline{R(K_q^\infty)}
    +c_3(j+1)^{-1}\mathbb{B}$, where we have used the fact that
$\overline{R(K_q^\infty)}$ is closed and the ball is compact.
Therefore,
\begin{align}
    \mathcal{A}_q
    &=
    \bigcap_{j\in\mathbb{Z}_{\geq0}}\mathcal{A}_{j,q}
    \nonumber\subseteq
    \bigcap_{j\in\mathbb{Z}_{\geq0}}
    \left(
    \overline{R(K_q^\infty)}
    +c_3(j+1)^{-1}\mathbb{B}
    \right)
    \nonumber\\
    &=
    \overline{R(K_q^\infty)}.
\@gobble{eq:second-inc}
\end{align}

The inclusions in \eqref{eq:first-inc} and \eqref{eq:second-inc} give us
$\mathcal{A}_q=\overline{R(K_q^\infty)}$. 


Finally, taking the union over $q\in\mathcal{Q}_{\text{tr}}$ and using
\eqref{eq:closureR0Kinf}, we obtain
\begin{align*}
\mathcal{B}
&=
\bigcup_{q\in\mathcal{Q}_{\text{tr}}}
\overline{R(K_q^\infty)}=\bigcup_{q\in\mathcal{Q}_{\text{tr}}}
\Bigg[
\{\xi_q^\ast\}\times\{q\}\times[0,1]
\\[-1mm]
&\left.
{}\cup
\bigcup_{r\in\mathcal{Q}_{\text{tr}}\setminus\{q\}}
\left(
\{\Theta_r^t(\Pi_r(\xi_q^\ast)):t\geq0\}
\cup\{\xi_r^\ast\}
\right)
\times\{r\}\times\{0\}
\right] \\
&= \mathcal{A}.
\end{align*}

This completes the proof.  \hfill $\blacksquare$
